CREATE TABLE `audit_context` (
	`id` integer PRIMARY KEY NOT NULL,
	`request_id` text NOT NULL,
	`actor_id` text NOT NULL,
	`actor_email` text NOT NULL,
	`actor_role` text NOT NULL,
	`owner_id` text NOT NULL,
	`path` text NOT NULL,
	`method` text NOT NULL,
	`action` text NOT NULL,
	`ip` text NOT NULL,
	`user_agent` text NOT NULL
);
--> statement-breakpoint
CREATE TABLE `audit_events` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`kind` text NOT NULL,
	`table_name` text NOT NULL,
	`target_id` text NOT NULL,
	`operation` text NOT NULL,
	`owner_id` text NOT NULL,
	`request_id` text NOT NULL,
	`actor_id` text NOT NULL,
	`actor_email` text NOT NULL,
	`actor_role` text NOT NULL,
	`path` text NOT NULL,
	`method` text NOT NULL,
	`action` text NOT NULL,
	`ip` text NOT NULL,
	`user_agent` text NOT NULL,
	`status` integer,
	`before_json` text,
	`after_json` text,
	`created_at` text NOT NULL
);
--> statement-breakpoint
CREATE INDEX `audit_events_owner_id` ON `audit_events` (`owner_id`,`id`);--> statement-breakpoint
CREATE INDEX `audit_events_actor_time` ON `audit_events` (`actor_email`,`created_at`);--> statement-breakpoint
CREATE INDEX `audit_events_target` ON `audit_events` (`table_name`,`target_id`,`id`);--> statement-breakpoint
CREATE TABLE `staff_access` (
	`email` text PRIMARY KEY NOT NULL,
	`owner_id` text NOT NULL,
	`role` text NOT NULL,
	`active` integer DEFAULT 1 NOT NULL,
	`reason` text NOT NULL,
	`granted_by` text NOT NULL,
	`updated_at` text NOT NULL
);
--> statement-breakpoint
CREATE INDEX `staff_access_owner` ON `staff_access` (`owner_id`,`active`);
--> statement-breakpoint
