 VALUES('change','temple_registry_meta',COALESCE(CAST(OLD."owner_id" AS TEXT),'')||':'||COALESCE(CAST(OLD."dataset_version" AS TEXT),''),'DELETE',OLD.owner_id,COALESCE((SELECT request_id FROM audit_context WHERE id=1),''),COALESCE((SELECT actor_id FROM audit_context WHERE id=1),''),COALESCE((SELECT actor_email FROM audit_context WHERE id=1),''),COALESCE((SELECT actor_role FROM audit_context WHERE id=1),'database'),COALESCE((SELECT path FROM audit_context WHERE id=1),''),COALESCE((SELECT method FROM audit_context WHERE id=1),''),COALESCE((SELECT action FROM audit_context WHERE id=1),''),COALESCE((SELECT ip FROM audit_context WHERE id=1),''),COALESCE((SELECT user_agent FROM audit_context WHERE id=1),''),NULL,json_object('owner_id',OLD."owner_id",'dataset_version',OLD."dataset_version",'source_filename',OLD."source_filename",'source_hash',OLD."source_hash",'rows_total',OLD."rows_total",'status',OLD."status",'started_at',OLD."started_at",'updated_at',OLD."updated_at",'imported_at',OLD."imported_at"),NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
END;
