CREATE TRIGGER evidence_no_replace BEFORE INSERT ON audit_events WHEN EXISTS(SELECT 1 FROM audit_events WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'Audit evidence is append-only'); END;
